theme.css:
/* theme: Mourning Stage | A second rail disaster mutes the election buzz while sports and markets flicker in the blue grief-shadow of the day */
/* mood: tragic */
/* layout: hero=classic; political-news=timeline/stack; financial-news=plain/stack; entertainment-news=lede/masonry; sports=outline/grid-2; music-releases=plain/stack; stock-analysis=stat/grid-2; outlook=tile/stack */
.diary-page {
  --paper: #0d1823;
  --paper-alt: #142235;
  --ink: #e8eff8;
  --ink-soft: #b9c6d6;
  --muted: #8b9cb0;
  --accent: #6f9fe8;
  --accent-ink: #08111c;
  --rule: #24364a;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
  background: var(--paper);
  color: var(--ink-soft);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-hero-inner {
  padding-block: 1.25rem 1.25rem;
}

.diary-page .diary-crumbs a {
  color: var(--muted);
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-kicker {
  margin-top: 0.5rem;
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--accent);
}

.diary-page .diary-title {
  margin-top: 0.4rem;
  max-width: 22ch;
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5.5vw, 4.2rem);
  font-weight: 400;
  letter-spacing: 0.01em;
  color: var(--ink);
  line-height: 1.05;
}

.diary-page .diary-summary {
  margin-top: 1rem;
  max-width: 40rem;
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  font-weight: 400;
  color: var(--ink-soft);
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
}

.diary-page .diary-theme-note {
  margin-top: 1rem;
  font-family: var(--font-ui);
  font-size: 0.82rem;
  color: var(--muted);
  letter-spacing: 0.02em;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  padding: 0.2rem 0.8rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.7rem;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 2.5rem;
}

.diary-page .diary-section-head {
  margin-bottom: 1.25rem;
  gap: 0.75rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 400;
  color: var(--ink);
  letter-spacing: 0.01em;
}

.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose > * + * {
  margin-top: 1.1em;
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--ink);
  margin-top: 2.2em;
}

.diary-page .diary-prose h3 + * {
  margin-top: 0.5em;
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 400;
  color: var(--ink);
  margin-top: 1.6em;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid currentColor;
  font-family: var(--font-ui);
  font-size: 0.68em;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: normal;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose em {
  font-style: italic;
}

.diary-page .diary-prose ul > li {
  position: relative;
  padding-left: 1.35rem;
}

.diary-page .diary-prose ul > li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.85em;
  width: 0.5rem;
  height: 2px;
  background: var(--accent);
}

.diary-page .diary-prose ol {
  list-style: decimal;
  padding-left: 1.5rem;
}

.diary-page .diary-prose ol > li::marker {
  font-family: var(--font-ui);
  font-size: 0.85em;
  font-weight: 600;
  color: var(--accent);
}

.diary-page .diary-prose li + li {
  margin-top: 0.5em;
}

.diary-page .diary-prose blockquote {
  border-left: 3px solid var(--accent);
  color: var(--ink);
  padding-left: 1.25rem;
  font-style: italic;
}

.diary-page .diary-prose hr {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-card {
  container-type: inline-size;
}

.diary-page .diary-card-inner {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
  height: 100%;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 400;
  line-height: 1.2;
  color: var(--ink);
}

.diary-page .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.7;
  color: var(--ink-soft);
}

.diary-page .diary-card-thread {
  align-self: flex-start;
  padding: 0.15rem 0.6rem;
  border: 1px solid var(--accent);
  border-radius: 0;
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--accent);
  background: transparent;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card-lede {
  padding-left: 0.75rem;
  border-left: 3px solid var(--accent);
  font-family: var(--font-display);
  font-size: 1.2rem;
  line-height: 1.45;
  color: var(--ink);
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2rem, 10cqi, 3rem);
  font-weight: 400;
  color: var(--accent);
  line-height: 1;
}

.diary-page .diary-card--stat .diary-card-inner {
  padding-top: 0.75rem;
  border-top: 2px solid var(--accent);
}

.diary-page .diary-card--outline .diary-card-inner {
  padding: 1.25rem;
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper-alt);
}

.diary-page .diary-card--timeline .diary-card-inner {
  position: relative;
  padding-left: 1.5rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.3rem;
  top: 0;
  bottom: -1.5rem;
  width: 2px;
  background: var(--rule);
}

.diary-page .diary-card--timeline:last-child .diary-card-inner::before {
  bottom: 0;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45rem;
  width: 0.6rem;
  height: 0.6rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--tile .diary-card-inner {
  padding: 1.25rem;
  background: var(--paper-alt);
}

.diary-page .diary-card--lede .diary-card-inner {
  border-left: 3px solid var(--accent);
  padding-left: 1rem;
}

.diary-page .diary-card--lede .diary-card-lede {
  border-left: 0;
  padding-left: 0;
  font-size: 1.15rem;
}

.diary-page .diary-stories--grid-2 {
  display: grid;
  gap: 1.25rem;
}

@container article (min-width: 40rem) {
  .diary-page .diary-stories--grid-2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.diary-page .diary-stories--stack {
  max-width: 46rem;
  gap: 2rem;
}

.diary-page .diary-stories--stack > .diary-card--timeline + .diary-card--timeline {
  padding-top: 0;
  border-top: 0;
}

.diary-page .diary-stories--masonry {
  display: block;
  columns: 2 19rem;
  column-gap: 1.5rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  break-inside: avoid;
  margin-bottom: 1.5rem;
}

.diary-page .diary-card--outline .diary-card-thread {
  margin-bottom: 0.5rem;
}

.diary-page .diary-card--timeline .diary-card-title {
  font-size: 1.15rem;
}

.diary-page .diary-card--timeline .diary-card-body {
  font-size: 1rem;
  line-height: 1.65;
}

.diary-page .diary-markets {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(9rem, 1fr));
  gap: 0.75rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  padding: 0.7rem 0.8rem 0.5rem;
}

.diary-page .diary-spark-label {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  color: var(--muted);
}

.diary-page .diary-spark-value {
  font-family: var(--font-ui);
  font-size: 0.92rem;
  color: var(--ink);
}

.diary-page .diary-spark-change {
  font-family: var(--font-ui);
  font-size: 0.72rem;
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

.diary-page .diary-toc {
  background: var(--paper);
}

.diary-page .diary-toc-label {
  color: var(--muted);
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover {
  color: var(--accent);
}

.diary-page .diary-crumbs a::before {
  content: "← ";
}

.diary-page .diary-section:first-child .diary-card--plain:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  font-size: 3.2em;
  font-weight: 400;
  line-height: 0.85;
  color: var(--accent);
  float: left;
  margin: 0.05em 0.1em 0 0;
}

@media (min-width: 1024px) {
  .diary-page .diary-hero-inner {
    display: grid;
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    column-gap: 3rem;
    align-items: end;
  }

  .diary-page .diary-crumbs,
  .diary-page .diary-kicker {
    grid-column: 1 / -1;
  }

  .diary-page .diary-title {
    grid-column: 1;
    grid-row: 3 / span 2;
    align-self: end;
  }

  .diary-page .diary-summary,
  .diary-page .diary-theme-note {
    grid-column: 2;
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
